  <script>
    const menuToggle = document.getElementById('menuToggle');
    const mobileMenu = document.getElementById('mobileMenu');

    menuToggle.addEventListener('click', () => {
      const open = mobileMenu.classList.toggle('open');
      menuToggle.setAttribute('aria-expanded', String(open));
      menuToggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    });

    const newsTrack = document.getElementById('newsTrack');
    let isDown = false;
    let startX = 0;
    let scrollStart = 0;

    newsTrack.addEventListener('pointerdown', (event) => {
      isDown = true;
      startX = event.clientX;
      scrollStart = newsTrack.scrollLeft;
      newsTrack.style.cursor = 'grabbing';
      newsTrack.setPointerCapture(event.pointerId);
    });

    newsTrack.addEventListener('pointermove', (event) => {
      if (!isDown) return;
      const delta = event.clientX - startX;
      newsTrack.scrollLeft = scrollStart - delta;
